par_dashboard_widget.component_props:
{"html":"<style>

  .shark-university-widget {
    font-family: 'Open Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    background-color: #f8fbfd;
    border-radius: 12px; 
    box-shadow: 0 6px 15px rgba(0, 0, 0, 0.08);
    border: 1px solid #e1e7ec;
    overflow: hidden;
    color: #333;
  }

  .shark-widget-header {
    background-color: #0d2c4c; 
    color: #ffffff;
    padding: 20px 25px;
    font-size: 1.6em;
    font-weight: 600;
    letter-spacing: 0.5px;
    display: flex;
    align-items: center;
    border-bottom: 2px solid #0a2542;
  }

  .shark-widget-header i {
    margin-right: 15px;
    font-size: 1.2em;
    color: #38bdf8;
  }

  .shark-widget-body {
    padding: 25px;
  }

  .shark-welcome {
    margin-bottom: 30px;
    border-bottom: 1px solid #e1e7ec;
    padding-bottom: 15px;
  }

  .shark-welcome h2 {
    font-size: 1.4em;
    font-weight: 600;
    color: #0d2c4c;
    margin-top: 0;
    margin-bottom: 8px;
  }

  .shark-welcome p {
    font-size: 1em;
    line-height: 1.5;
    color: #5c6c7b;
    margin: 0;
  }

  .shark-section-title {
    font-size: 1.1em;
    font-weight: 600;
    color: #0d2c4c;
    margin-top: 0;
    margin-bottom: 20px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .shark-actions-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr); 
    gap: 20px;
    margin-bottom: 30px;
  }

  .shark-action-card {
    background-color: #ffffff;
    border: 1px solid #e1e7ec;
    border-radius: 10px;
    padding: 25px 20px;
    text-align: center;
    text-decoration: none;
    color: #0d2c4c;
    transition: all 0.3s ease; 
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
  }

  .shark-action-card:hover {
    border-color: #38bdf8;
    transform: translateY(-5px); 
    box-shadow: 0 4px 10px rgba(56, 189, 248, 0.15);
  }

  .shark-action-card i {
    font-size: 2.5em;
    color: #38bdf8;
    margin-bottom: 15px;
  }

  .shark-action-card .action-text {
    font-size: 1em;
    font-weight: 600;
    line-height: 1.2;
  }

  .shark-quickaccess-list {
    background-color: #ffffff;
    border: 1px solid #e1e7ec;
    border-radius: 10px;
    padding: 15px;
    margin: 0;
    list-style: none;
  }

  .shark-quickaccess-item {
    border-bottom: 1px solid #eee;
  }

  .shark-quickaccess-item:last-child {
    border-bottom: none;
  }

  .shark-quickaccess-link {
    display: flex;
    align-items: center;
    text-decoration: none;
    padding: 12px 10px;
    transition: background-color 0.2s ease;
    border-radius: 6px;
  }

  .shark-quickaccess-link:hover {
    background-color: #f1f8fc;
  }

  .quickaccess-icon {
    font-size: 1.2em;
    color: #38bdf8;
    margin-right: 15px;
    width: 25px; 
    text-align: center;
  }

  .quickaccess-text {
    font-size: 1em;
    color: #333;
    font-weight: 500;
  }

</style>
<div class="shark-university-widget">
<div class="shark-widget-header">Shark University - Admin Central</div>
<div class="shark-widget-body">
<div class="shark-welcome">
<h2>Welcome!</h2>
<p>Your centralized command center to streamline training management.</p>
</div>
<div class="shark-actions-section">
<h3 class="shark-section-title">Quick Actions</h3>
<div class="shark-actions-grid"><a class="shark-action-card" href="/x_1590365_shark_0_course.do?sys_id=-1"> <span class="action-text">Create New Course</span> </a> <a class="shark-action-card" href="/x_1590365_shark_0_training_session.do?sys_id=-1"> <span class="action-text">Create New Session</span> </a> <a class="shark-action-card" href="/x_1590365_shark_0_enrollment.do?sys_id=-1"> <span class="action-text">Enroll Student</span> </a></div>
</div>
<div class="shark-quickaccess-section">
<h3 class="shark-section-title">My Quick Access</h3>
<ul class="shark-quickaccess-list">
<li class="shark-quickaccess-item"><a class="shark-quickaccess-link" href="/x_1590365_shark_0_enrollment_list.do?sysparm_query=state%3D3"> <span class="quickaccess-text">My Approved Enrollments</span> </a></li>
<li class="shark-quickaccess-item"><a class="shark-quickaccess-link" href="/x_1590365_shark_0_training_session_list.do"> <span class="quickaccess-text">My Training Sessions</span> </a></li>
<li class="shark-quickaccess-item"><a class="shark-quickaccess-link" href="/x_1590365_shark_0_enrollment_list.do?sysparm_query=state%3D2"> <span class="quickaccess-text">All Pending Approvals</span> </a></li>
<li class="shark-quickaccess-item"><a class="shark-quickaccess-link" href="/x_1590365_shark_0_course_list.do"> <span class="quickaccess-text">Available Courses</span> </a></li>
</ul>
</div>
</div>
</div>","id":"html","value":"<style>

